<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM seed_count_records WHERE id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('記録がありません');}$ob=db()->prepare('SELECT object_number,centroid_x,centroid_y FROM seed_morphology_objects WHERE record_id=? ORDER BY object_number');$ob->execute([$id]);$objects=$ob->fetchAll();$analysis=json_decode((string)$r['analysis_json'],true)?:[];$iw=(float)($analysis['image']['width_px']??1);$ih=(float)($analysis['image']['height_px']??1);$latest=['deleted'=>[],'added'=>[]];try{$cs=db()->prepare('SELECT deleted_object_ids,added_points FROM seed_manual_corrections WHERE record_id=? ORDER BY id DESC LIMIT 1');$cs->execute([$id]);if($c=$cs->fetch())$latest=['deleted'=>json_decode((string)$c['deleted_object_ids'],true)?:[],'added'=>json_decode((string)$c['added_points'],true)?:[]];}catch(Throwable$e){}
?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=2.1.0"><title>粒数の手動補正</title></head><body><header><h1>粒数の手動補正</h1><nav><a href="detail.php?id=<?=$id?>">詳細へ戻る</a><a href="history.php">履歴</a></nav></header><main><section class="card"><p>「追加」は見落とした種子の中央を、「削除」は誤検出された番号の近くをタップします。自動解析データは削除されず、補正履歴として保存されます。</p><div class="manual-toolbar"><button id="addMode" class="secondary selected" type="button">＋ カウント追加</button><button id="deleteMode" class="secondary" type="button">－ カウント削除</button><button id="undo" class="secondary" type="button">1操作戻す</button><button id="reset" class="secondary" type="button">補正をリセット</button></div><p>自動検出 <b id="autoCount"><?=count($objects)?></b>粒 ／ 補正後 <b id="correctedCount">-</b>粒</p><div class="manual-editor"><img id="resultImage" src="<?=h($r['result_path'])?>" alt="解析結果"><canvas id="editor"></canvas></div><form id="saveForm"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="record_id" value="<?=$id?>"><label>補正メモ<input name="note" maxlength="255" placeholder="例：影の誤検出を2粒削除"></label><button class="primary" id="save" type="submit">補正した粒数を保存</button><div id="status"></div></form></section></main><script>const objects=<?=json_encode(array_map(function($o)use($iw,$ih){return['id'=>(int)$o['object_number'],'x'=>(float)$o['centroid_x']/$iw,'y'=>(float)$o['centroid_y']/$ih];},$objects),JSON_UNESCAPED_SLASHES)?>,initial=<?=json_encode($latest,JSON_UNESCAPED_SLASHES)?>,img=document.querySelector('#resultImage'),canvas=document.querySelector('#editor'),ctx=canvas.getContext('2d');let mode='add',deleted=new Set((initial.deleted||[]).map(Number)),added=(initial.added||[]).map(p=>({x:Number(p.x),y:Number(p.y)})),undo=[];function resize(){canvas.width=img.clientWidth;canvas.height=img.clientHeight;draw()}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.lineWidth=3;ctx.font='bold 18px sans-serif';objects.forEach(o=>{if(!deleted.has(o.id))return;const x=o.x*canvas.width,y=o.y*canvas.height;ctx.strokeStyle='#e12727';ctx.beginPath();ctx.moveTo(x-10,y-10);ctx.lineTo(x+10,y+10);ctx.moveTo(x+10,y-10);ctx.lineTo(x-10,y+10);ctx.stroke()});added.forEach((p,i)=>{const x=p.x*canvas.width,y=p.y*canvas.height;ctx.fillStyle='#00a65a';ctx.beginPath();ctx.arc(x,y,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.fillText('+',x-6,y+6)});document.querySelector('#correctedCount').textContent=objects.length-deleted.size+added.length}function pt(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}function snapshot(){undo.push({deleted:[...deleted],added:added.map(p=>({...p}))});if(undo.length>50)undo.shift()}canvas.addEventListener('pointerdown',e=>{const p=pt(e);snapshot();if(mode==='add')added.push(p);else{let best=null,dist=.06;objects.forEach(o=>{if(deleted.has(o.id))return;const d=Math.hypot(o.x-p.x,o.y-p.y);if(d<dist){dist=d;best=o}});if(best)deleted.add(best.id);else undo.pop()}draw()});function select(m){mode=m;document.querySelector('#addMode').classList.toggle('selected',m==='add');document.querySelector('#deleteMode').classList.toggle('selected',m==='delete')}document.querySelector('#addMode').onclick=()=>select('add');document.querySelector('#deleteMode').onclick=()=>select('delete');document.querySelector('#undo').onclick=()=>{const s=undo.pop();if(s){deleted=new Set(s.deleted);added=s.added;draw()}};document.querySelector('#reset').onclick=()=>{snapshot();deleted=new Set();added=[];draw()};document.querySelector('#saveForm').onsubmit=async e=>{e.preventDefault();const b=document.querySelector('#save'),s=document.querySelector('#status'),d=new FormData(e.target);d.set('deleted',JSON.stringify([...deleted]));d.set('added',JSON.stringify(added));b.disabled=true;s.textContent='保存しています…';try{const r=await fetch('correction_api.php',{method:'POST',body:d}),j=await r.json();if(!r.ok||!j.success)throw new Error(j.error||'保存できません');location.href=j.detail_url}catch(x){s.textContent='エラー: '+x.message;b.disabled=false}};img.addEventListener('load',resize);window.addEventListener('resize',resize);if(img.complete)resize();</script></body></html>
